# fix_fase2.ps1 — Corrige arquivos da Fase 2 Neural via base64
$base = "C:\Users\fabri\Downloads\PURAL_EDITORIAL_V47_12_PREMIUM_OPERACIONAL\PURAL_EDITORIAL_V47_12_PREMIUM_OPERACIONAL"

function Decode-AndWrite {
    param($b64, $path)
    $bytes = [System.Convert]::FromBase64String($b64)
    $fullPath = Join-Path $base $path
    $dir = Split-Path $fullPath -Parent
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    [System.IO.File]::WriteAllBytes($fullPath, $bytes)
    Write-Host "[OK] $path ($($bytes.Length) bytes)" -ForegroundColor Green
}

Write-Host "=== FIX FASE 2 ===" -ForegroundColor Cyan

$sandbox_b64 = ""
$patch_b64 = ""
$integrador_b64 = ""

Decode-AndWrite $sandbox_b64 "sistema\ururau_ai_auditor\nn_engine\sandbox_ml.py"
Decode-AndWrite $patch_b64 "sistema\ururau_ai_auditor\nn_engine\patch_generator.py"
Decode-AndWrite $integrador_b64 "sistema\ururau_ai_auditor\nn_engine\integrador.py"

Write-Host "" 
Write-Host "CONCLUIDO. Rode agora:" -ForegroundColor Cyan
Write-Host "  cd "$base"" -ForegroundColor Yellow
Write-Host "  .\47_REPARO_NEURAL.bat" -ForegroundColor Yellow
